import{_ as s,C as r,o,c as i,a6 as l,E as d,j as a,a as n}from"./chunks/framework.CKIbuWFA.js";const q=JSON.parse('{"title":"日付を指定して統計を確認する","description":"","frontmatter":{"title":"日付を指定して統計を確認する","docId":"user.points.statistics","translationKey":"user.points.statistics","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"a7333d75baa9aec6e0c4afb69d1c773575a56ee8da982f0fa5a11a73b903ec2d","translationRevision":"bf19680ae5ceef35d0e67c06563e497a8474884dca93e99bcb5821c98420814c","order":20},"headers":[],"relativePath":"ja/user/points/statistics.md","filePath":"ja/user/points/statistics.md","lastUpdated":1794611623000}'),c={name:"ja/user/points/statistics.md"};function u(p,e,h,m,f,b){const t=r("DemoFrame");return o(),i("div",null,[e[0]||(e[0]=l('<h1 id="review-statistics-across-dates" tabindex="-1">日付を指定して統計を確認する <a class="header-anchor" href="#review-statistics-across-dates" aria-label="Permalink to &quot;日付を指定して統計を確認する {#review-statistics-across-dates}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>配信者の活動を必要な期間で比較し、表示フィードやポイント残高と合計が違う理由を理解します。この環境に活動が記録され、<a href="./../live/connections.html">接続</a> で目的の配信者が選択されている必要があります。Cloud サインインはローカル統計のデータ源ではありません。</p><h2 id="query-the-recorded-period" tabindex="-1">記録済み期間を照会する <a class="header-anchor" href="#query-the-recorded-period" aria-label="Permalink to &quot;記録済み期間を照会する {#query-the-recorded-period}&quot;">​</a></h2><ol><li><strong>分析</strong> を開き、日付欄の横の配信者を確認します。選択した配信者によって照会する保存済み集計が決まります。</li><li><strong>今日</strong>、<code>7d</code>、<code>30d</code>、<code>90d</code>、または任意期間を選びます。任意の日付は開始・終了を明示し、前後関係を確認します。</li><li>比較前に表示期間とセッション数を読みます。ローカル日付の境界はタイムゾーン差を使い、PC のタイムゾーンを変えると期間の解釈も変わる場合があります。</li><li>チャット、ギフト、いいね、ダイヤモンド、最大視聴者数から指標を選びます。活動グラフで期間を比較し、貢献者表で返された上位視聴者を確認します。</li><li>貢献者検索は返されたデータに含まれる視聴者が対象です。過去の全視聴者を無制限に検索する機能ではありません。</li><li>新しい活動の後やページに戻った際は <strong>更新</strong> を選びます。数値の共有時は配信者、日付、指標も記録します。</li></ol><p>現在のページは配信者と日付範囲でネイティブの <code>analytics.summary</code> を呼びます。過去のセッションを含む永続化済み集計を読み、現在のフィード内に残るイベントには限定されません。統計 DB は集計を保存し、チャット全文は保存しません。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>永続化されたローカル統計と期間照会を利用できます。記録のない日付で活動が返らないのは正常です。ポイントは<a href="./rules.html">付与率</a>、手動調整、自動化の付与による別の測定なので、残高と一致しない場合があります。ダイヤモンド、ギフト数、ポイントは置き換え可能な単位ではありません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>データがなければ貢献者検索を消し、期間を広げ、配信者を確認して更新します。ホストエラーでは診断コードを保持し、接続復旧後に再試行します。フィード消去で統計は消えません。新規データディレクトリに過去履歴はないため、環境移行では<a href="./../preferences/backups.html">バックアップ</a> を使います。</p>',10)),d(t,{scenario:"analytics",locale:"ja",title:"デモ: 統計"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[n("運用の詳細 "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "運用の詳細 {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"Analytics は選択した配信者と日付範囲の上位貢献者を現在 10 人取得します。検索対象は受信した部分集合で、全視聴者検索ではありません。永続集計の期間・単位は、フィードのセッション内ダイヤ・いいねランキングやポイント残高とは異なります。書き出しや比較では配信者・日付・指標も残してください。",-1))])}const v=s(c,[["render",u]]);export{q as __pageData,v as default};
